where h.create_time >= #{beginTime}
  and h.create_time < #{endTime}
  and (s.del_flag is null or s.del_flag = '0')

and f.fire_point_id = #{firePointId}
and s.sensor_id = #{deviceId}
${params.dataScope}

where h.gps_time >= #{beginTime}
  and h.gps_time < #{endTime}
  and (g.del_flag is null or g.del_flag = '0')

and f.fire_point_id = #{firePointId}
and g.gateway_id = #{deviceId}
${params.dataScope}
